softmax_hip_source = """
#include <hip/hip_runtime.h>
#include <cmath>

#define BLOCK_SIZE 256

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Each block processes one row
    extern __shared__ float shared_data[];

    // First pass: find max value for numerical stability
    float max_val = -INFINITY;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = input[row * dim + i];
        if (val > max_val) max_val = val;
    }

    // Store max in shared memory and perform block reduction
    shared_data[threadIdx.x] = max_val;
    __syncthreads();

    // Block-level reduction for max
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) {
            shared_data[threadIdx.x] = fmaxf(shared_data[threadIdx.x], shared_data[threadIdx.x + stride]);
        }
        __syncthreads();
    }

    max_val = shared_data[0];
    __syncthreads();

    // Second pass: compute exp(x - max) and sum
    float sum = 0.0f;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        float val = expf(input[row * dim + i] - max_val);
        output[row * dim + i] = val;
        sum += val;
    }

    // Store sum in shared memory and perform block reduction
    shared_data[threadIdx.x] = sum;
    __syncthreads();

    // Block-level reduction for sum
    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) {
            shared_data[threadIdx.x] += shared_data[threadIdx.x + stride];
        }
        __syncthreads();
    }

    sum = shared_data[0];
    __syncthreads();

    // Third pass: normalize
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        output[row * dim + i] /= sum;
    }
}

torch::Tensor softmax_hip(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto dim = input.size(1);
    auto output = torch::empty_like(input);

    const int block_size = BLOCK_SIZE;
    const int num_blocks = batch_size;
    const int shared_memory_size = block_size * sizeof(float);

    softmax_kernel<<<num_blocks, block_size, shared_memory_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        dim
    );

    return output;
}
"""

softmax_hip = load_inline(
    name="softmax_hip",
    cpp_sources=softmax_hip_source,
    functions=["softmax_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softmax_hip = softmax_hip

    def forward(self, x):
        return self.softmax_hip.softmax_hip(x)

def get_inputs():
    batch_size = 4096
    dim = 393216
    x = torch.rand(batch_size, dim).cuda()
    return [x]

def get_init_inputs():
    return []

import os
