# Define the HIP kernel for 2D convolution with shared memory
conv2d_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_WIDTH 32
#define KERNEL_SIZE 3

__global__ void conv2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out
) {
    // Shared memory for input tile
    __shared__ float input_tile[TILE_WIDTH + KERNEL_SIZE - 1][TILE_WIDTH + KERNEL_SIZE - 1];

    // Output position
    int row_out = blockIdx.y * TILE_WIDTH + threadIdx.y;
    int col_out = blockIdx.x * TILE_WIDTH + threadIdx.x;

    // Batch and output channel
    int b = blockIdx.z / out_channels;
    int oc = blockIdx.z % out_channels;

    // Valid output check
    if (b >= batch_size) return;

    // Input tile top-left corner in global memory
    int row_in_start = blockIdx.y * TILE_WIDTH;
    int col_in_start = blockIdx.x * TILE_WIDTH;

    // Initialize accumulation
    float sum = 0.0f;

    // Loop over input channels
    for (int ic = 0; ic < in_channels; ic++) {
        // Load input tile into shared memory collaboratively
        for (int dy = 0; dy < KERNEL_SIZE; dy += TILE_WIDTH) {
            for (int dx = 0; dx < KERNEL_SIZE; dx += TILE_WIDTH) {
                int row_in = row_in_start + threadIdx.y + dy;
                int col_in = col_in_start + threadIdx.x + dx;

                // Load element if within bounds
                if (row_in < height_in && col_in < width_in) {
                    int input_idx = ((b * in_channels + ic) * height_in + row_in) * width_in + col_in;
                    input_tile[threadIdx.y + dy][threadIdx.x + dx] = input[input_idx];
                } else {
                    input_tile[threadIdx.y + dy][threadIdx.x + dx] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute convolution for this output position
        if (row_out < height_out && col_out < width_out) {
            for (int kr = 0; kr < KERNEL_SIZE; kr++) {
                for (int kc = 0; kc < KERNEL_SIZE; kc++) {
                    int row_in = threadIdx.y + kr;
                    int col_in = threadIdx.x + kc;
                    float input_val = input_tile[row_in][col_in];
                    float weight_val = weight[((oc * in_channels + ic) * KERNEL_SIZE + kr) * KERNEL_SIZE + kc];
                    sum += input_val * weight_val;
                }
            }
        }

        __syncthreads();
    }

    // Write output
    if (row_out < height_out && col_out < width_out) {
        int output_idx = ((b * out_channels + oc) * height_out + row_out) * width_out + col_out;
        output[output_idx] = sum;
    }
}

torch::Tensor conv2d_hip_forward(
    torch::Tensor input,
    torch::Tensor weight
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int height_in = input.size(2);
    const int width_in = input.size(3);

    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);

    const int height_out = height_in - kernel_size + 1;
    const int width_out = width_in - kernel_size + 1;

    auto output = torch::zeros({batch_size, out_channels, height_out, width_out}, 
                               input.options());

    dim3 block_dim(TILE_WIDTH, TILE_WIDTH, 1);
    dim3 grid_dim(
        (width_out + TILE_WIDTH - 1) / TILE_WIDTH,
        (height_out + TILE_WIDTH - 1) / TILE_WIDTH,
        batch_size * out_channels
    );

    hipLaunchKernelGGL(
        conv2d_kernel,
        grid_dim,
        block_dim,
        0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        height_in,
        width_in,
        height_out,
        width_out
    );

    return output;
}
"""

# Compile the HIP kernel
conv2d_hip = load_inline(
    name='conv2d_hip',
    cpp_sources=conv2d_hip_source,
    functions=['conv2d_hip_forward'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert stride == 1, "Only stride=1 is supported"
        assert padding == 0, "Only padding=0 is supported"
        assert dilation == 1, "Only dilation=1 is supported"
        assert groups == 1, "Only groups=1 is supported"
        assert bias == False, "Only bias=False is supported"

        self.weight = nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, kernel_size))
        self.kernel_size = kernel_size
        self.conv2d_hip = conv2d_hip

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dim() == 4, "Input must be 4D tensor (batch, channels, height, width)"
        assert x.size(1) == self.weight.size(1), "Input channels must match weight channels"
        assert self.kernel_size == 3, "Only kernel_size=3 is currently optimized"

        return self.conv2d_hip.conv2d_hip_forward(x, self.weight)

def get_inputs():
    batch_size = 16
    in_channels = 16
    height = 1024
    width = 1024
    x = torch.rand(batch_size, in_channels, height, width, device='cuda', dtype=torch.float32)
    return [x]

def get_init_inputs():
    in_channels = 16
    out_channels = 128
    kernel_size = 3
    return [in_channels, out_channels, kernel_size]

