matmul_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/types.h>

#define BLOCK_SIZE_M 128
#define BLOCK_SIZE_N 128
#define BLOCK_SIZE_K 32

__global__ void tall_skinny_matmul_kernel(
    const float* A, const float* B, float* C,
    int M, int N, int K) {

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column positions
    int row = by * BLOCK_SIZE_M + ty;
    int col = bx * BLOCK_SIZE_N + tx;

    // Shared memory for tiling
    __shared__ float As[BLOCK_SIZE_M][BLOCK_SIZE_K];
    __shared__ float Bs[BLOCK_SIZE_K][BLOCK_SIZE_N];

    float sum = 0.0f;

    // Loop over all tiles of K
    for (int t = 0; t < (K + BLOCK_SIZE_K - 1) / BLOCK_SIZE_K; ++t) {
        // Load tile from A into shared memory
        int a_col = t * BLOCK_SIZE_K + tx;
        if (row < M && a_col < K) {
            As[ty][tx] = A[row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        int b_row = t * BLOCK_SIZE_K + ty;
        if (b_row < K && col < N) {
            Bs[ty][tx] = B[b_row * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < BLOCK_SIZE_K; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(BLOCK_SIZE_N, BLOCK_SIZE_M);
    dim3 gridDim((N + BLOCK_SIZE_N - 1) / BLOCK_SIZE_N, 
                 (M + BLOCK_SIZE_M - 1) / BLOCK_SIZE_M);

    tall_skinny_matmul_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K);

    return C;
}
"""

tall_skinny_matmul = load_inline(
    name="tall_skinny_matmul",
    cpp_sources=matmul_cpp_source,
    functions=["matmul_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = tall_skinny_matmul

    def forward(self, A, B):
        return self.matmul.matmul_hip(A.cuda(), B.cuda())

