#include <hip/hip_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Shared memory for tiles
    __shared__ float tile_A[TILE_SIZE][TILE_SIZE];
    __shared__ float tile_B[TILE_SIZE][TILE_SIZE];

    // Row and column indices for this thread
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    // Initialize accumulator
    float sum = 0.0f;

    // Loop over tiles of K dimension
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tile of A into shared memory
        int load_row_A = blockIdx.y * TILE_SIZE + threadIdx.y;
        int load_col_A = t * TILE_SIZE + threadIdx.x;
        if (load_row_A < M && load_col_A < K) {
            tile_A[threadIdx.y][threadIdx.x] = A[load_row_A * K + load_col_A];
        } else {
            tile_A[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int load_row_B = t * TILE_SIZE + threadIdx.y;
        int load_col_B = blockIdx.x * TILE_SIZE + threadIdx.x;
        if (load_row_B < K && load_col_B < N) {
            tile_B[threadIdx.y][threadIdx.x] = B[load_row_B * N + load_col_B];
        } else {
            tile_B[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += tile_A[threadIdx.y][k] * tile_B[k][threadIdx.x];
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to C
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

