    int ow = threadIdx.x;  // output width

    if (n >= N || c >= C || oh >= OH) return;

    // Calculate starting position in input
    int ih_start = oh * SH - PH;
    int iw_start = ow * SW - PW;

    float max_val = -FLT_MAX;

    // Unrolled loops for kernel size 4 (KH=4, KW=4)
    // This reduces loop overhead and helps with instruction scheduling
    #pragma unroll
    for (int kh = 0; kh < 4; kh++) {
        int ih = ih_start + kh * DH;
        bool h_valid = (ih >= 0 && ih < H);

        #pragma unroll
        for (int kw = 0; kw < 4; kw++) {
            int iw = iw_start + kw * DW;
            bool w_valid = (iw >= 0 && iw < W);

            // Only load from memory if indices are valid
            if (h_valid && w_valid) {
                float val = input[((n * C + c) * H + ih) * W + iw];
                max_val = fmaxf(max_val, val);
