layer_norm_hip_code = """
#include <hip/hip_runtime.h>
#include <math.h>

#define THREADS_PER_BLOCK 256

__global__ void layer_norm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int normalized_size,
    float eps
) {
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* batch_input = input + batch_idx * normalized_size;
    float* batch_output = output + batch_idx * normalized_size;

    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int warps_per_block = (THREADS_PER_BLOCK + 31) >> 5;

    __shared__ float shared_sum[32];
    __shared__ float shared_var_sum[32];
    __shared__ float mean;
    __shared__ float rstd;

    // Phase 1: Compute sum for mean using efficient parallel reduction
    float local_sum = 0.0f;
    #pragma unroll 4
    for (int i = tid; i < normalized_size; i += THREADS_PER_BLOCK) {
        local_sum += batch_input[i];
    }

    // Warp-level reduction using XOR shuffle for better performance
    #pragma unroll
    for (int mask = 16; mask > 0; mask >>= 1) {
        local_sum += __shfl_xor(local_sum, mask);
    }

    // Store warp sum to shared memory
    if (lane == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    // Block-level reduction (only first warp participates)
    if (warp_id == 0) {
        float warp_sum = (lane < warps_per_block) ? shared_sum[lane] : 0.0f;
        #pragma unroll
        for (int mask = 16; mask > 0; mask >>= 1) {
            warp_sum += __shfl_xor(warp_sum, mask);
        }
        if (lane == 0) {
            mean = warp_sum / normalized_size;
        }
    }
    __syncthreads();

    // Phase 2: Compute sum of squared differences for variance
    float local_var_sum = 0.0f;
    #pragma unroll 4
    for (int i = tid; i < normalized_size; i += THREADS_PER_BLOCK) {
        float diff = batch_input[i] - mean;
        local_var_sum += diff * diff;
    }

    // Warp-level reduction for variance
    #pragma unroll
    for (int mask = 16; mask > 0; mask >>= 1) {
        local_var_sum += __shfl_xor(local_var_sum, mask);
    }

    // Store warp var sum to shared memory
    if (lane == 0) {
        shared_var_sum[warp_id] = local_var_sum;
    }
    __syncthreads();

    // Block-level reduction for variance (only first warp)
    if (warp_id == 0) {
        float warp_var_sum = (lane < warps_per_block) ? shared_var_sum[lane] : 0.0f;
        #pragma unroll
        for (int mask = 16; mask > 0; mask >>= 1) {
            warp_var_sum += __shfl_xor(warp_var_sum, mask);
        }
        if (lane == 0) {
            float variance = warp_var_sum / normalized_size;
            rstd = rsqrtf(variance + eps);  // Use rsqrtf for better performance
        }
    }
    __syncthreads();

    // Phase 3: Fused normalize, scale, and bias
    #pragma unroll 4
    for (int i = tid; i < normalized_size; i += THREADS_PER_BLOCK) {
        float normalized = (batch_input[i] - mean) * rstd;
        batch_output[i] = normalized * weight[i] + bias[i];
    }
}

torch::Tensor layer_norm_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float eps) {
    int batch_size = input.size(0);
