cross_entropy_source = """
#include <hip/hip_runtime.h>
#include <cmath>

#define WARP_SIZE 32
#define BLOCK_SIZE 256
#define NUM_WARPS (BLOCK_SIZE / WARP_SIZE)

__global__ void cross_entropy_forward_kernel(
    const float* predictions,
    const long* targets,
    float* loss_per_sample,
    int batch_size,
    int num_classes) {

    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    extern __shared__ float shared_data[];
    float* shared_pred = shared_data;
    float* warp_max = &shared_data[num_classes];
    float* warp_sum = &shared_data[num_classes + NUM_WARPS];

    int tid = threadIdx.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;

    // Load predictions into shared memory
    for (int i = tid; i < num_classes; i += BLOCK_SIZE) {
        shared_pred[i] = predictions[batch_idx * num_classes + i];
    }
    __syncthreads();

    // Find max in parallel
    float local_max = -INFINITY;
    for (int i = tid; i < num_classes; i += BLOCK_SIZE) {
        local_max = fmaxf(local_max, shared_pred[i]);
    }

    // Warp-level reduction for max
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        local_max = fmaxf(local_max, __shfl_down(local_max, offset));
    }

    // Store warp max in shared memory
    if (lane_id == 0) {
        warp_max[warp_id] = local_max;
    }
    __syncthreads();

    // First thread finds global max
    float block_max = -INFINITY;
    if (tid == 0) {
        for (int i = 0; i < NUM_WARPS; i++) {
            block_max = fmaxf(block_max, warp_max[i]);
        }
        // Store in first warp_max slot for broadcasting
        warp_max[0] = block_max;
    }
    __syncthreads();
    block_max = warp_max[0];

    // Compute exp sum
    float local_sum = 0.0f;
    for (int i = tid; i < num_classes; i += BLOCK_SIZE) {
        float val = expf(shared_pred[i] - block_max);
        local_sum += val;
    }

    // Warp-level reduction for sum
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset);
    }

    // Store warp sum in shared memory
    if (lane_id == 0) {
        warp_sum[warp_id] = local_sum;
    }
    __syncthreads();

    // First thread computes final loss
    if (tid == 0) {
        float block_sum = 0.0f;
        for (int i = 0; i < NUM_WARPS; i++) {
            block_sum += warp_sum[i];
        }

        int target_class = targets[batch_idx];
        float target_pred = predictions[batch_idx * num_classes + target_class];
        loss_per_sample[batch_idx] = logf(block_sum) - (target_pred - block_max);
    }
}

__global__ void sum_loss_kernel(
    const float* loss_per_sample,
    float* total_loss,
    int batch_size) {

    int tid = threadIdx.x;
    int idx = blockIdx.x * BLOCK_SIZE + tid;

    // Grid-stride loop for sum
    float sum = 0.0f;
    for (int i = idx; i < batch_size; i += gridDim.x * BLOCK_SIZE) {
        sum += loss_per_sample[i];
    }

    // Block-level reduction
    __shared__ float block_sum[BLOCK_SIZE];
    block_sum[tid] = sum;
    __syncthreads();

    for (int offset = BLOCK_SIZE/2; offset > 0; offset /= 2) {
        if (tid < offset) {
            block_sum[tid] += block_sum[tid + offset];
        }
        __syncthreads();
    }

    // Write final result
    if (tid == 0) {
        atomicAdd(total_loss, block_sum[0] / batch_size);
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure contiguous memory layout
    predictions = predictions.contiguous();
    targets = targets.contiguous();

    auto batch_size = predictions.size(0);
    auto num_classes = predictions.size(1);

    // Allocate intermediate storage
    auto loss_per_sample = torch::zeros({batch_size}, predictions.options());
    auto total_loss = torch::zeros({1}, predictions.options());

    // Launch forward kernel
    const int num_blocks = batch_size;
    const int shared_memory_size = (num_classes + NUM_WARPS * 2) * sizeof(float);

    hipLaunchKernelGGL(
        cross_entropy_forward_kernel,
        dim3(num_blocks), dim3(BLOCK_SIZE), shared_memory_size,
        predictions.data_ptr<float>(),
        targets.data_ptr<long>(),
        loss_per_sample.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Launch reduction kernel
    const int sum_blocks = (batch_size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    hipLaunchKernelGGL(
        sum_loss_kernel,
        dim3(sum_blocks), dim3(BLOCK_SIZE), 0,
        loss_per_sample.data_ptr<float>(),
        total_loss.data_ptr<float>(),
        batch_size
    );

    return total_loss;
}
"""

