#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <cmath>

#define BLOCK_SIZE 512
// Each thread processes multiple elements to improve compute/memory ratio
#define ELEMENTS_PER_THREAD 16

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int dim) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    if (row >= batch_size) return;

    // Shared memory for reductions and max value
    __shared__ float sdata[BLOCK_SIZE];

    int tid = threadIdx.y * blockDim.x + threadIdx.x;

    // Vectorized processing - each thread handles ELEMENTS_PER_THREAD contiguous elements
    int base_idx = row * dim + threadIdx.y * ELEMENTS_PER_THREAD * blockDim.x + threadIdx.x * ELEMENTS_PER_THREAD;

    // Find max value
    float local_max = -INFINITY;
    for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
        int idx = base_idx + i * blockDim.x;
        if (idx < row * dim + dim) {
            float val = input[idx];
            if (val > local_max) local_max = val;
        }
    }
    sdata[tid] = local_max;
    __syncthreads();

    // Wave-level reduction using butterfly pattern
    #pragma unroll
    for (int offset = blockDim.x * blockDim.y / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + offset]);
        }
        __syncthreads();
    }

    float row_max = sdata[0];
    __syncthreads();

    // Compute exp(x - max) and sum
    float local_sum = 0.0f;
    for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
        int idx = base_idx + i * blockDim.x;
        if (idx < row * dim + dim) {
            float val = expf(input[idx] - row_max);
            output[idx] = val;
            local_sum += val;
        }
    }
    sdata[tid] = local_sum;
    __syncthreads();

    // Wave-level reduction for sum
    #pragma unroll
    for (int offset = blockDim.x * blockDim.y / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            sdata[tid] += sdata[tid + offset];
        }
        __syncthreads();
    }

    float row_sum = sdata[0];

    // Normalize
    for (int i = 0; i < ELEMENTS_PER_THREAD; i++) {
        int idx = base_idx + i * blockDim.x;
        if (idx < row * dim + dim) {
            output[idx] /= row_sum;
        }
    }
}

torch::Tensor softmax_hip(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto dim = input.size(1);
    auto output = torch::empty_like(input);

    // Use 2D grid for better occupancy and easier thread management
    int threads_x = ELEMENTS_PER_THREAD > 1 ? 32 : 64;
    int threads_y = BLOCK_SIZE / threads_x;
    dim3 block_size(threads_x, threads_y);
    dim3 grid_size((dim + ELEMENTS_PER_THREAD * BLOCK_SIZE - 1) / (ELEMENTS_PER_THREAD * BLOCK_SIZE), 
                   (batch_size + threads_y - 1) / threads_y);

    softmax_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
