#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

#define BLOCK_SIZE 256

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K
) {
    int row = blockIdx.x;
    if (row >= M) return;

    __shared__ float s_data[BLOCK_SIZE];

    int tid = threadIdx.x;
    float sum = 0.0f;
    const float* A_row = A + row * K;

    // Each thread computes partial sum over strided elements
    // Threads access memory coalesced: thread i accesses elements at i, i+BLOCK_SIZE, i+2*BLOCK_SIZE, etc.
    for (int i = tid; i < K; i += blockDim.x) {
        sum += A_row[i] * B[i];
    }

    s_data[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }

    // Thread 0 writes the final result for this row
    if (tid == 0) {
        C[row] = s_data[0];
    }
}

