        __syncthreads();

        // Compute using shared memory tiles
        // Each thread computes a 4x4 block of C
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE_K; k++) {
            // Load 4 elements from As for this thread
            float a_vals[4];
            int a_row = ty * 4;
            #pragma unroll
            for (int i = 0; i < 4; i++) {
