    // Precompute row/col indices for this thread
    int thread_row_base = thread_id / (TILE_N / THREAD_N);
    int thread_col_base = thread_id % (TILE_N / THREAD_N);

    // Loop over tiles of K dimension
    for (int tile_k = 0; tile_k < K; tile_k += TILE_K) {
        // Load tile of A into shared memory using 2D indexing
        #pragma unroll
        for (int i = 0; i < TILE_M; i += blockDim.y) {
            int load_row = block_row + i + ty;
            #pragma unroll
            for (int j = 0; j < TILE_K; j += blockDim.x) {
                int load_col = tile_k + j + tx;
                if (load_row < M && load_col < K) {
