struct float4_vec {
    float x, y, z, w;
};

__device__ __forceinline__ float gelu_scalar(float x) {
    // Fast GELU computation using tanh approximation
    float x3 = x * x * x;
    float inner = SQRT_2_OVER_PI * (x + COEFF * x3);
    float tanh_val = tanhf(inner);
    return 0.5f * x * (1.0f + tanh_val);
