#include <hip/hip_runtime.h>
#include <torch/types.h>

#define BLOCK_SIZE_X 32
#define BLOCK_SIZE_Y 32

__global__ void tall_skinny_matmul_kernel(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index (2D block)
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column positions in output matrix C
    int row = by * BLOCK_SIZE_Y + ty;
    int col = bx * BLOCK_SIZE_X + tx;

    // Accumulator for the dot product
    float sum = 0.0f;

    // Loop over all elements in the K dimension
    // Since K is small (32), we can process it in one iteration per thread
    for (int k = 0; k < K; ++k) {
        if (row < M && col < N) {
            float a_val = A[row * K + k];  // A is M x K
            float b_val = B[k * N + col];  // B is K x N
            sum += a_val * b_val;
        }
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_hip(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 blockDim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 gridDim((N + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, 
                 (M + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y);

    tall_skinny_matmul_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N);

    return C;
}
"""

