max_pool_hip_source = """
#include <hip/hip_runtime.h>
#include <float.h>

#define BLOCK_SIZE_X 16  // threads per block in x dimension
#define BLOCK_SIZE_Y 16  // threads per block in y dimension

__global__ void max_pool_2d_hip_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int KH, int KW, int SH, int SW,
    int PH, int PW, int DH, int DW,
    int OH, int OW
) {
    // Input shape: [N, C, H, W]
    // Output shape: [N, C, OH, OW]

    int n = blockIdx.z;  // batch index
    int c = blockIdx.y;  // channel index

    // Calculate output position
    int ow = blockIdx.x * BLOCK_SIZE_X + threadIdx.x;  // output width
    int oh = blockIdx.y * BLOCK_SIZE_Y + threadIdx.y;  // output height (wait, this is wrong)

    // Actually, we need to use blockIdx.y for channels, so let's calculate differently
    // Re-calculate: we need to distribute threads across output height and width
    // Use 1D grid for batch and channel, 2D blocks for height/width
    // Actually, let's use a cleaner approach:
    n = blockIdx.x;  // batch
    c = blockIdx.y;  // channel  
    ow = threadIdx.x;  // width
    oh = threadIdx.y;  // height

    // Each block handles one (batch, channel)
    // Each thread handles one (height, width) position in output
    if (n >= N || c >= C || oh >= OH || ow >= OW) return;

    // Calculate starting position in input
    int ih_start = oh * SH - PH;
    int iw_start = ow * SW - PW;

    float max_val = -FLT_MAX;

    // Loop through kernel elements
    for (int kh = 0; kh < KH; kh++) {
        int ih = ih_start + kh * DH;
        if (ih < 0 || ih >= H) continue;

        for (int kw = 0; kw < KW; kw++) {
            int iw = iw_start + kw * DW;
            if (iw < 0 || iw >= W) continue;

            float val = input[((n * C + c) * H + ih) * W + iw];
            max_val = fmaxf(max_val, val);
        }
    }

    output[((n * C + c) * OH + oh) * OW + ow] = max_val;
}

torch::Tensor max_pool_2d_hip(torch::Tensor input, 
                              int kernel_h, int kernel_w,
                              int stride_h, int stride_w, 
                              int pad_h, int pad_w,
                              int dilation_h, int dilation_w) {

    auto input_cuda = input.cuda();
    auto N = input_cuda.size(0);   // batch
    auto C = input_cuda.size(1);   // channels
    auto H = input_cuda.size(2);   // height
    auto W = input_cuda.size(3);   // width

    // Calculate output dimensions
    int OH = (H + 2 * pad_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    int OW = (W + 2 * pad_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({N, C, OH, OW}, input_cuda.options());

    if (output.numel() == 0) {
        return output;
    }

    // Launch grid: each (batch, channel) gets its own block
    dim3 block_dim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 grid_dim(N, C);

    hipLaunchKernelGGL(
        max_pool_2d_hip_kernel,
        grid_dim,
        block_dim,
        0, 0,
        input_cuda.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        kernel_h, kernel_w, stride_h, stride_w,
        pad_h, pad_w, dilation_h, dilation_w,
        OH, OW
    );

    return output;
}
