__global__ void layer_norm_hip_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int normalized_size,
    float eps
) {
    int bid = blockIdx.x;
    int tid = threadIdx.x;

    const float* batch_input = input + bid * normalized_size;
    float* batch_output = output + bid * normalized_size;

    __shared__ float s_mean;
    __shared__ float s_rstd;
    __shared__ float s_sum[BLOCK_SIZE];

    // Step 1: Compute mean using parallel reduction
    float sum = 0.0f;
    for (int i = tid; i < normalized_size; i += BLOCK_SIZE) {
        sum += batch_input[i];
    }
    s_sum[tid] = sum;
    __syncthreads();

    // Block-level reduction using shared memory
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        s_mean = s_sum[0] / normalized_size;
    }
    __syncthreads();

    // Step 2: Compute variance using parallel reduction
    float var_sum = 0.0f;
    for (int i = tid; i < normalized_size; i += BLOCK_SIZE) {
        float diff = batch_input[i] - s_mean;
        var_sum += diff * diff;
    }
    s_sum[tid] = var_sum;
    __syncthreads();

    // Block-level reduction for variance
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float variance = s_sum[0] / normalized_size;
        s_rstd = rsqrtf(variance + eps);
    }
    __syncthreads();

    // Step 3: Apply normalization, scale, and bias
    for (int i = tid; i < normalized_size; i += BLOCK_SIZE) {
        float normalized = (batch_input[i] - s_mean) * s_rstd;
        batch_output[i] = normalized * weight[i] + bias[i];
    }
