softmax_hip_source = """
#include <hip/hip_runtime.h>
#include <cmath>
#include <cfloat>

#define BLOCK_SIZE 512
#define ELEMENTS_PER_THREAD 64
#define WARP_SIZE 64

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int batch_size, int dim) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* input_row = &input[row * dim];
    float* output_row = &output[row * dim];

    // Each thread processes ELEMENTS_PER_THREAD elements
    float local_max = -FLT_MAX;
    float local_sum = 0.0f;

    // First pass: find max (vectorized)
    #pragma unroll
    for (int i = threadIdx.x; i < dim; i += blockDim.x * ELEMENTS_PER_THREAD) {
        #pragma unroll
        for (int j = 0; j < ELEMENTS_PER_THREAD && (i + j * blockDim.x) < dim; j++) {
            int idx = i + j * blockDim.x;
            float val = input_row[idx];
            if (val > local_max) local_max = val;
        }
    }

    // Warp-level reduction for max
    __shared__ float shared_max[BLOCK_SIZE / WARP_SIZE];
    int lane_id = threadIdx.x % WARP_SIZE;
    int warp_id = threadIdx.x / WARP_SIZE;

    // Shuffle reduction within warp
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        float other_max = __shfl_down(local_max, offset);
        if (lane_id + offset < WARP_SIZE) {
            local_max = fmaxf(local_max, other_max);
        }
    }

    if (lane_id == 0) {
        shared_max[warp_id] = local_max;
    }
    __syncthreads();

    if (threadIdx.x < (BLOCK_SIZE / WARP_SIZE)) {
        local_max = shared_max[threadIdx.x];
    } else {
        local_max = -FLT_MAX;
    }

    // Final reduction across warps
    if (warp_id == 0) {
        for (int offset = (BLOCK_SIZE / WARP_SIZE) / 2; offset > 0; offset /= 2) {
            if (lane_id + offset < (BLOCK_SIZE / WARP_SIZE)) {
                float other_max = __shfl_down(local_max, offset);
                local_max = fmaxf(local_max, other_max);
            }
        }
    }

    // Broadcast max back to all threads
    float row_max = __shfl(local_max, 0);

    // Second pass: compute exp(x - max) and sum
    #pragma unroll
    for (int i = threadIdx.x; i < dim; i += blockDim.x * ELEMENTS_PER_THREAD) {
        #pragma unroll
        for (int j = 0; j < ELEMENTS_PER_THREAD && (i + j * blockDim.x) < dim; j++) {
            int idx = i + j * blockDim.x;
            float val = expf(input_row[idx] - row_max);
            output_row[idx] = val;
            local_sum += val;
        }
    }

    // Warp-level reduction for sum (same pattern as max)
    __shared__ float shared_sum[BLOCK_SIZE / WARP_SIZE];

    // Shuffle reduction within warp
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        float other_sum = __shfl_down(local_sum, offset);
        if (lane_id + offset < WARP_SIZE) {
            local_sum += other_sum;
        }
    }

    if (lane_id == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    if (threadIdx.x < (BLOCK_SIZE / WARP_SIZE)) {
        local_sum = shared_sum[threadIdx.x];
    } else {
        local_sum = 0.0f;
    }

    // Final reduction across warps
    if (warp_id == 0) {
        for (int offset = (BLOCK_SIZE / WARP_SIZE) / 2; offset > 0; offset /= 2) {
            if (lane_id + offset < (BLOCK_SIZE / WARP_SIZE)) {
                float other_sum = __shfl_down(local_sum, offset);
                local_sum += other_sum;
            }
        }
    }

    // Broadcast sum back to all threads
    float row_sum = __shfl(local_sum, 0);
    float inv_sum = 1.0f / row_sum;

    // Final pass: normalize
    #pragma unroll
    for (int i = threadIdx.x; i < dim; i += blockDim.x * ELEMENTS_PER_THREAD) {
        #pragma unroll
        for (int j = 0; j < ELEMENTS_PER_THREAD && (i + j * blockDim.x) < dim; j++) {
            int idx = i + j * blockDim.x;
            output_row[idx] *= inv_sum;
        }
    }
}

torch::Tensor softmax_hip(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto dim = input.size(1);

    auto output = torch::empty_like(input, torch::TensorOptions().memory_format(torch::MemoryFormat::Contiguous));

    const int block_size = BLOCK_SIZE;
    const int num_blocks = batch_size;

    softmax_kernel<<<num_blocks, block_size>>>(
        input.contiguous().data_ptr<const float>(),
        output.data_ptr<float>(),
        batch_size,
        dim
    );

    return output;
}
