matvec_hip_source = """
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

// Smaller block size for better occupancy and more blocks
#define BLOCK_SIZE 128

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K
) {
    int row = blockIdx.x;
    if (row >= M) return;

    __shared__ float s_data[BLOCK_SIZE];

    int tid = threadIdx.x;
    float sum = 0.0f;
    const float* __restrict__ A_row = A + row * K;

    // Each thread processes elements with stride equal to block size
    // This creates coalesced memory access across the warp
    for (int i = tid; i < K; i += blockDim.x) {
        sum += A_row[i] * B[i];
    }

    s_data[tid] = sum;
    __syncthreads();

    // Optimized parallel reduction using warp-level operations
    // First, reduce within each warp (no sync needed)
    #pragma unroll
    for (int s = blockDim.x / 2; s > 32; s >>= 1) {
        if (tid < s) {
            s_data[tid] += s_data[tid + s];
        }
        __syncthreads();
    }

    // Final warp reduction - no __syncthreads() needed
    if (tid < 32) {
        volatile float* s_ptr = s_data;
        s_ptr[tid] += s_ptr[tid + 32];
        s_ptr[tid] += s_ptr[tid + 16];
        s_ptr[tid] += s_ptr[tid + 8];
        s_ptr[tid] += s_ptr[tid + 4];
        s_ptr[tid] += s_ptr[tid + 2];
        s_ptr[tid] += s_ptr[tid + 1];
    }

    // Thread 0 writes the final result
    if (tid == 0) {
        C[row] = s_data[0];
    }
}

torch::Tensor matvec_hip(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.device().is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.device().is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    int M = A.size(0);
    int K = A.size(1);

    TORCH_CHECK(B.size(0) == K, "B dim 0 must match A dim 1");
    TORCH_CHECK(B.size(1) == 1, "B must be Kx1");

    auto C = torch::zeros({M, 1}, A.options());

    const int block_size = BLOCK_SIZE;
    const int grid_size = M;

    // Get the current HIP stream
    hipStream_t stream = c10::hip::getCurrentHIPStream(A.device().index());

    hipLaunchKernelGGL(
        matvec_kernel,
        dim3(grid_size),
        dim3(block_size),
        0, // shared memory size (already allocated statically)
        stream,
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K
    );

    hipError_t error = hipGetLastError();
    if (error != hipSuccess) {
        TORCH_CHECK(false, "HIP kernel launch error: ", hipGetErrorString(error));
