# Highly optimized HIP kernel using warp-level primitives
matvec_hip_source = """
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

#define BLOCK_SIZE 256
#define WARP_SIZE 32
#define WARPS_PER_BLOCK (BLOCK_SIZE / WARP_SIZE)

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K
) {
    // Each block computes WARPS_PER_BLOCK output elements
    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp_id;

    if (row >= M) return;

    float sum = 0.0f;
    const float* __restrict__ A_row = A + row * K;

    // Each thread in warp loads consecutive elements (perfect coalescing)
    // lane_id accesses elements at: lane_id, lane_id+32, lane_id+64, ...
    for (int i = lane_id; i < K; i += WARP_SIZE) {
        sum += A_row[i] * B[i];
    }

    // Warp-level reduction using shuffle (no shared memory!)
    // This is faster on AMD GPUs
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down(sum, offset);
    }

    // Thread 0 of each warp writes the result
    if (lane_id == 0) {
        C[row * 1 + 0] = sum; // Explicit (M, 1) shape
    }
}

torch::Tensor matvec_hip(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.device().is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.device().is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");

    int M = A.size(0);
    int K = A.size(1);

    TORCH_CHECK(B.size(0) == K, "B dim 0 must match A dim 1");
    TORCH_CHECK(B.size(1) == 1, "B must be Kx1");

    auto C = torch::zeros({M, 1}, A.options());

    const int block_size = BLOCK_SIZE;
    const int grid_size = (M + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;

    // Get the current HIP stream
    hipStream_t stream = c10::hip::getCurrentHIPStream(A.device().index());

    hipLaunchKernelGGL(
        matvec_kernel,
        dim3(grid_size),
        dim3(block_size),
        0, // no shared memory needed
        stream,
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K
    );

    hipError_t error = hipGetLastError();
    if (error != hipSuccess) {
        TORCH_CHECK(false, "HIP kernel launch error: ", hipGetErrorString(error));
    }

    return C;
}
"""

