cross_entropy_source = """
#include <hip/hip_runtime.h>
#include <cmath>

#define WARP_SIZE 32
#define BLOCK_SIZE 256

typedef float float32_t;
typedef long int64_t;

__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void cross_entropy_forward_kernel(
    const float32_t* __restrict__ predictions,
    const int64_t* __restrict__ targets,
    float32_t* __restrict__ loss_per_sample,
    int batch_size,
    int num_classes) {

    int batch_idx = blockIdx.x * blockDim.y + threadIdx.y;
    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;
    int lane_id = tid % WARP_SIZE;

    // Each thread processes a subset of the classes
    float local_max = -INFINITY;
    float local_sum = 0.0f;
    int target_class = -1;

    if (tid == 0) {
        target_class = targets[batch_idx];
    }
    target_class = __shfl(target_class, 0);

    // Grid-stride loop over classes for better memory coalescing
    // Process 4 elements per thread for more efficient memory bandwidth
    for (int i = tid; i < num_classes; i += blockDim.x) {
        float pred = predictions[batch_idx * num_classes + i];
        local_max = fmaxf(local_max, pred);

        // Store prediction for target class
        if (i == target_class) {
            local_sum = pred;  // Reuse local_sum to store target prediction
        }
    }

    // Warp reduction for max
    float warp_max = warp_reduce_max(local_max);

    // Get target prediction value from the thread that has it
    float target_pred = local_sum;
    if (lane_id == 0) {
        // Share target prediction within warp
        target_pred = __shfl(target_pred, target_class % WARP_SIZE);
    }
    target_pred = __shfl(target_pred, 0);

    // Second pass: compute exp sum
    local_sum = 0.0f;
    for (int i = tid; i < num_classes; i += blockDim.x) {
        float pred = predictions[batch_idx * num_classes + i];
        local_sum += expf(pred - warp_max);
    }

    // Warp reduction for sum
    float warp_sum = warp_reduce_sum(local_sum);

    // Thread 0 computes final loss
    if (tid == 0) {
        loss_per_sample[batch_idx] = logf(warp_sum) - (target_pred - warp_max);
    }
}

__global__ void sum_loss_kernel(
    const float32_t* __restrict__ loss_per_sample,
    float32_t* __restrict__ total_loss,
    int batch_size) {

    int tid = threadIdx.x;
    int idx = blockIdx.x * BLOCK_SIZE + tid;

    // Grid-stride loop for better GPU utilization
    float sum = 0.0f;
    for (int i = idx; i < batch_size; i += gridDim.x * BLOCK_SIZE) {
        sum += loss_per_sample[i];
    }

    // Block-level reduction
    __shared__ float block_sum[BLOCK_SIZE];
    block_sum[tid] = sum;
    __syncthreads();

    for (int offset = BLOCK_SIZE/2; offset > 0; offset /= 2) {
        if (tid < offset) {
            block_sum[tid] += block_sum[tid + offset];
        }
        __syncthreads();
    }

    // Write final result
    if (tid == 0) {
        atomicAdd(total_loss, block_sum[0] / batch_size);
    }
}

torch::Tensor cross_entropy_hip(torch::Tensor predictions, torch::Tensor targets) {
    // Ensure on GPU and contiguous
    predictions = predictions.cuda().contiguous();
    targets = targets.cuda().contiguous().to(torch::kLong);

    auto batch_size = predictions.size(0);
    auto num_classes = predictions.size(1);

    // Allocate intermediate storage
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
    auto loss_per_sample = torch::zeros({batch_size}, options);
    auto total_loss = torch::zeros({1}, options);

