    const int warps_per_sm = 32;  // Target occupancy
    const int desired_blocks = num_sms * warps_per_sm / (BLOCK_SIZE / WARP_SIZE);

    // Launch forward kernel with optimized grid
    const int num_blocks = std::min(desired_blocks, (batch_size + 3) / 4);  // 4 warps per block
    const int threads_per_block = BLOCK_SIZE;

    hipStream_t stream = at::cuda::getCurrentCUDAStream();
