        cross_entropy_forward_kernel,
        dim3(num_blocks), dim3(threads_per_block), 0, stream,
        predictions.data_ptr<float>(),
        targets.data_ptr<long>(),
        loss_per_sample.data_ptr<float>(),
        batch_size,
        num_classes
    );

    // Launch reduction kernel
    const int sum_blocks = std::min(512, (batch_size + BLOCK_SIZE - 1) / BLOCK_SIZE);
    hipLaunchKernelGGL(
        sum_loss_kernel,
        dim3(sum_blocks), dim3(BLOCK_SIZE), 0, stream,
        loss_per_sample.data_ptr<float>(),
        total_loss.data_ptr<float>(),
