    auto out = torch::empty_like(x);

    const int block_size = 64;  // Match feature dimension for coalesced access
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    rms_norm_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        eps,
        total_elements,
        features
    );

    return out;
}
