# HIP kernel with shared memory tiling for optimized matrix multiplication
matmul_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 32
#define TILE_SIZE 32

__global__ void matmul_hip(const float* A, const float* B, float* C, int N) {
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Row and column of the output element
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Shared memory tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Accumulator
    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load A tile into shared memory
        int a_idx = row * N + t * TILE_SIZE + tx;
        As[ty][tx] = (row < N && (t * TILE_SIZE + tx) < N) ? A[a_idx] : 0.0f;

        // Load B tile into shared memory
        int b_idx = (t * TILE_SIZE + ty) * N + col;
        Bs[ty][tx] = ((t * TILE_SIZE + ty) < N && col < N) ? B[b_idx] : 0.0f;

        __syncthreads();

        // Compute dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    // Define grid and block dimensions
    dim3 block_dim(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid_dim((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    // Launch kernel with ROCm-style syntax
    hipLaunchKernelGGL(matmul_hip, grid_dim, block_dim, 0, 0, 
                       A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

matmul_hip = load_inline(
    name="matmul_hip",
    cpp_sources=matmul_cpp_source,
    functions=["matmul"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_hip

