#include <hip/hip_runtime.h>
#include <torch/types.h>

// For tall-skinny (M=32768, K=32, N=32768), we optimize for K=32
#define BLOCK_SIZE_M 64
#define BLOCK_SIZE_N 64
#define K_SIZE 32  // We know K is small and can fit in shared memory

__global__ void tall_skinny_matmul_kernel(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index (2D block)
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int thread_id = ty * blockDim.x + tx;

    // Global positions
    int row = by * BLOCK_SIZE_M + ty;
    int col = bx * BLOCK_SIZE_N + tx;

    // Shared memory for A tile (BLOCK_SIZE_M x K)
    __shared__ float As[BLOCK_SIZE_M][K_SIZE];
    // Shared memory for B tile (K x BLOCK_SIZE_N)
    __shared__ float Bs[K_SIZE][BLOCK_SIZE_N];

    float sum = 0.0f;

    // Since K is small (32), load entire K dimension in shared memory
    // Load A tile: each thread loads one element from A
    int a_row = by * BLOCK_SIZE_M + ty;
    for (int k = tx; k < K; k += blockDim.x) {
        if (a_row < M) {
            As[ty][k] = A[a_row * K + k];
        } else {
            As[ty][k] = 0.0f;
        }
    }

    // Load B tile: each thread loads one element from B
    for (int k = ty; k < K; k += blockDim.y) {
        if (col < N) {
            Bs[k][tx] = B[k * N + col];
        } else {
            Bs[k][tx] = 0.0f;
        }
    }

    __syncthreads();

    // Compute: each thread computes dot product of its row from As and column from Bs
    if (row < M && col < N) {
        for (int k = 0; k < K; ++k) {
            sum += As[ty][k] * Bs[k][tx];
        }
