#include <hip/hip_runtime.h>

#define TILE_WIDTH 16
#define KERNEL_SIZE 3
#define INPUT_TILE_WIDTH (TILE_WIDTH + KERNEL_SIZE - 1)

__global__ void conv2d_optimized_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out
) {
    // Shared memory for input tile - only one channel at a time
    __shared__ float input_tile[INPUT_TILE_WIDTH][INPUT_TILE_WIDTH];

    // Batch and output channel indices
    int b = blockIdx.z / out_channels;
    int oc = blockIdx.z % out_channels;

    // Output position this thread computes
    int row_out = blockIdx.y * TILE_WIDTH + threadIdx.y;
    int col_out = blockIdx.x * TILE_WIDTH + threadIdx.x;

    // Check if we're computing a valid output position
    bool valid_output = (row_out < height_out && col_out < width_out);

    // Top-left corner of the input tile in global memory
    int row_in_start = blockIdx.y * TILE_WIDTH;
    int col_in_start = blockIdx.x * TILE_WIDTH;

    float sum = 0.0f;

    // Loop over input channels
    for (int ic = 0; ic < in_channels; ic++) {
        // Load input tile into shared memory (one channel at a time)
        // Each thread loads multiple elements if needed
        for (int i = threadIdx.y; i < INPUT_TILE_WIDTH; i += TILE_WIDTH) {
            for (int j = threadIdx.x; j < INPUT_TILE_WIDTH; j += TILE_WIDTH) {
                int row_in = row_in_start + i;
                int col_in = col_in_start + j;

                if (row_in < height_in && col_in < width_in) {
                    int input_idx = ((b * in_channels + ic) * height_in + row_in) * width_in + col_in;
                    input_tile[i][j] = input[input_idx];
                } else {
                    input_tile[i][j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute convolution for this input channel
        if (valid_output) {
            // Thread position within the input tile
            int row_in = threadIdx.y;
            int col_in = threadIdx.x;

            // Accumulate convolution sum
            for (int kr = 0; kr < KERNEL_SIZE; kr++) {
                for (int kc = 0; kc < KERNEL_SIZE; kc++) {
                    float input_val = input_tile[row_in + kr][col_in + kc];
                    float weight_val = weight[((oc * in_channels + ic) * KERNEL_SIZE + kr) * KERNEL_SIZE + kc];
                    sum += input_val * weight_val;
                }
            }
        }

        __syncthreads();
    }

    // Write output
    if (valid_output) {
        int output_idx = ((b * out_channels + oc) * height_out + row_out) * width_out + col_out;
        output[output_idx] = sum;
    }
