depthwise_conv2d_hip_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_WIDTH 16
#define TILE_HEIGHT 16
#define KERNEL_SIZE 3
#define INPUT_TILE_WIDTH (TILE_WIDTH + KERNEL_SIZE - 1)
#define INPUT_TILE_HEIGHT (TILE_HEIGHT + KERNEL_SIZE - 1)

__global__ void depthwise_conv2d_tiled_kernel(
    const float* input,
    const float* weight,
    float* output,
    const int batch_size,
    const int in_channels,
    const int height,
    const int width,
    const int stride,
    const int padding,
    const int height_out,
    const int width_out
) {
    // Input: (batch, in_channels, height, width)
    // Weight: (out_channels, in_channels/groups, kernel_h, kernel_w) = (in_channels, 1, kernel_h, kernel_w)
    // Output: (batch, out_channels, height_out, width_out) = (batch, in_channels, height_out, width_out)

    const int batch = blockIdx.z / in_channels;
    const int channel = blockIdx.z % in_channels;
    const int out_row_base = blockIdx.y * TILE_HEIGHT;
    const int out_col_base = blockIdx.x * TILE_WIDTH;

    // Thread indices within output tile
    const int thread_out_row = threadIdx.y;
    const int thread_out_col = threadIdx.x;

    // Thread indices within input tile (shared memory)
    const int thread_in_row = threadIdx.y;
    const int thread_in_col = threadIdx.x;

    // Position in the output
    const int out_row = out_row_base + thread_out_row;
    const int out_col = out_col_base + thread_out_col;

    // Early exit if outside output bounds
    if (out_row >= height_out || out_col >= width_out) return;

    // Calculate input start position for this tile
    const int in_row_start = out_row_base * stride - padding;
    const int in_col_start = out_col_base * stride - padding;

    // Shared memory for input tile
    __shared__ float input_tile[INPUT_TILE_HEIGHT][INPUT_TILE_WIDTH];

    // Load shared memory with input tile data
    // Each thread loads one element from global to shared memory
    const int in_row = in_row_start + thread_in_row;
    const int in_col = in_col_start + thread_in_col;

    float input_val = 0.0f;
    if (in_row >= 0 && in_row < height && in_col >= 0 && in_col < width) {
        const float* input_ptr = input + ((batch * in_channels + channel) * height * width);
        input_val = input_ptr[in_row * width + in_col];
    }

    input_tile[thread_in_row][thread_in_col] = input_val;
    __syncthreads();

    // Pointers to current channel
    const float* weight_ptr = weight + channel * (1 * KERNEL_SIZE * KERNEL_SIZE);
    float* output_ptr = output + ((batch * in_channels + channel) * height_out * width_out);

    // Perform convolution using shared memory
    float sum = 0.0f;

    // Compute kernel indices based on stride position
    const int kernel_offset_row = (out_row % stride);
    const int kernel_offset_col = (out_col % stride);

    // Unrolled convolution loop - use shared memory for input data
    #pragma unroll
    for (int kh = 0; kh < KERNEL_SIZE; kh++) {
        // Shared memory indices
        const int shared_row = thread_in_row * stride + kh - kernel_offset_row;

        // Skip if outside shared memory bounds
        if (shared_row >= 0 && shared_row < INPUT_TILE_HEIGHT) {
            #pragma unroll
            for (int kw = 0; kw < KERNEL_SIZE; kw++) {
                const int shared_col = thread_in_col * stride + kw - kernel_offset_col;

                // Skip if outside shared memory bounds
                if (shared_col >= 0 && shared_col < INPUT_TILE_WIDTH) {
                    const float input_val = input_tile[shared_row][shared_col];
                    const float weight_val = weight_ptr[kh * KERNEL_SIZE + kw];
                    sum += input_val * weight_val;
                }
            }
        }
    }

    output_ptr[out_row * width_out + out_col] = sum;
}

// Fallback to regular kernel for non-stride=1 cases
torch::Tensor depthwise_conv2d_hip(
    torch::Tensor input,
    torch::Tensor weight,
    const int stride,
    const int padding
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int height = input.size(2);
    const int width = input.size(3);
    const int kernel_size = weight.size(2);

    const int height_out = (height + 2 * padding - kernel_size) / stride + 1;
    const int width_out = (width + 2 * padding - kernel_size) / stride + 1;

