    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int K,
    int K_BLOCKS,
    int M, int N) {

    // Each thread computes 8 elements in a row
    const int thread_row = blockIdx.y * BLOCK_SIZE + threadIdx.y * THREAD_BLOCK_SIZE;
    const int thread_col = blockIdx.x * BLOCK_SIZE + threadIdx.x * THREAD_BLOCK_SIZE;

    // Shared memory for A and B tiles
    __shared__ float As[BLOCK_SIZE][K_BLOCK_SIZE];
    __shared__ float Bs[K_BLOCK_SIZE][BLOCK_SIZE];

    // Registers for accumulating results (8 elements per thread)
    float sum[THREAD_BLOCK_SIZE];
    for (int i = 0; i < THREAD_BLOCK_SIZE; ++i) {
        sum[i] = 0.0f;
    }

    int col_idx, row_idx;

    // Loop over K tiles
    for (int t = 0; t < K_BLOCKS; ++t) {
        // Load A tile into shared memory (each thread loads 8 elements)
        row_idx = thread_row + threadIdx.x * THREAD_BLOCK_SIZE;
        col_idx = t * K_BLOCK_SIZE;

        if (row_idx < M && col_idx < K) {
            As[threadIdx.y * THREAD_BLOCK_SIZE][threadIdx.x * THREAD_BLOCK_SIZE] = A[row_idx * K + col_idx];
        } else {
            As[threadIdx.y * THREAD_BLOCK_SIZE][threadIdx.x * THREAD_BLOCK_SIZE] = 0.0f;
        }

        // Load B tile into shared memory (each thread loads 8 elements)
        row_idx = t * K_BLOCK_SIZE;
        col_idx = thread_col + threadIdx.y * THREAD_BLOCK_SIZE;

        if (col_idx < N && row_idx < K) {
            Bs[threadIdx.x * THREAD_BLOCK_SIZE][threadIdx.y * THREAD_BLOCK_SIZE] = 
                B[row_idx * N + col_idx];
        } else {
            Bs[threadIdx.x * THREAD_BLOCK_SIZE][threadIdx.y * THREAD_BLOCK_SIZE] = 0.0f;
        }

        __syncthreads();

        // Compute dot product
        for (int k = 0; k < K_BLOCK_SIZE; ++k) {
            float a_val = As[threadIdx.y * THREAD_BLOCK_SIZE][k];
            for (int i = 0; i < THREAD_BLOCK_SIZE; ++i) {
                float b_val = Bs[k][threadIdx.x * THREAD_BLOCK_SIZE + i];
                sum[i] += a_val * b_val;
            }
        }

        __syncthreads();
    }

    // Write results to C (vectorized stores)
    if (thread_row < M) {
        for (int i = 0; i < THREAD_BLOCK_SIZE; ++i) {
            col_idx = thread_col + i;
            if (col_idx < N) {
                C[thread_row * N + col_idx] = sum[i];
            }
        }
    }
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    // For square matrices
    int N = A.size(0);

    auto C = torch::zeros_like(A);

    // Dimensions
    int M = N;  // rows
    int K = N;  // common dimension
    int N_cols = N;  // columns

    int K_BLOCKS = (K + K_BLOCK_SIZE - 1) / K_BLOCK_SIZE;

    // Calculate grid dimensions
    int blocks_x = (N_cols + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int blocks_y = (M + BLOCK_SIZE - 1) / BLOCK_SIZE;

    dim3 block_dim(BLOCK_SIZE / THREAD_BLOCK_SIZE, BLOCK_SIZE / THREAD_BLOCK_SIZE);
    dim3 grid_dim(blocks_x, blocks_y);

    // Launch kernel
    hipLaunchKernelGGL(matmul_kernel, grid_dim, block_dim, 0, 0,
        A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(),
        K, K_BLOCKS, M, N_cols);

    return C;
}
