#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>

#define BLOCK_SIZE 256
#define VEC_SIZE 8  // Vectorized loads for better bandwidth

__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K
) {
    int row = blockIdx.x;
    if (row >= M) return;

    __shared__ float shared_mem[BLOCK_SIZE];

    int tid = threadIdx.x;
    float sum = 0.0f;
    const float* __restrict__ A_row = A + row * K;

    // Process elements in blocks of VEC_SIZE with aligned access
    // This ensures coalesced memory access across the warp
    for (int i = tid; i < K; i += blockDim.x) {
        sum += A_row[i] * __ldg(&B[i]);  // Use __ldg for cached read of B
    }

    shared_mem[tid] = sum;
    __syncthreads();

    // Optimized parallel reduction
    // First reduce to 32 elements (one per warp)
    if (tid < 32) {
        for (int i = tid + 32; i < BLOCK_SIZE; i += 32) {
            shared_mem[tid] += shared_mem[i];
        }
    }
    __syncthreads();

    // Final warp reduction for thread 0
    if (tid < 32) {
        float val = shared_mem[tid];
        // Unroll the reduction for better performance
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            val += __shfl_down(val, offset);
        }
        if (tid == 0) {
            C[row * 1 + 0] = val;
        }
    }
}

