    __shared__ float As[BLOCK_SIZE_Y][K_SIZE];
    __shared__ float Bs[K_SIZE][BLOCK_SIZE_X];

    float sum = 0.0f;

    // Load A tile into shared memory
    // Each thread loads its corresponding elements from A
    if (row < M) {
