#include <hip/hip_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N) {

    // Calculate the thread's position in the output matrix
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    // Loop over tiles
    for (int t = 0; t < num_tiles; ++t) {
        // Calculate the indices for loading A and B
        int A_row = blockIdx.y * TILE_SIZE + threadIdx.y;
        int A_col = t * TILE_SIZE + threadIdx.x;

        // Load A tile (with bounds checking)
        if (A_row < N && A_col < N) {
            As[threadIdx.y][threadIdx.x] = A[A_row * N + A_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        int B_row = t * TILE_SIZE + threadIdx.y;
        int B_col = blockIdx.x * TILE_SIZE + threadIdx.x;

        // Load B tile (with bounds checking)
        if (B_row < N && B_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[B_row * N + B_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result with bounds checking
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros_like(A);

    // Define grid and block dimensions
    dim3 block_dim(TILE_SIZE, TILE_SIZE);
    dim3 grid_dim((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel with ROCm-style syntax
    hipLaunchKernelGGL(matmul_kernel, grid_dim, block_dim, 0, 0,
                       A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
