#include <hip/hip_runtime.h>

#define TILE_WIDTH 32
#define KERNEL_SIZE 3

__global__ void conv2d_optimized_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height_in,
    int width_in,
    int height_out,
    int width_out
) {
    // Output position this thread computes
    int row_out = blockIdx.y * blockDim.y + threadIdx.y;
    int col_out = blockIdx.x * blockDim.x + threadIdx.x;

    // Batch and output channel indices
    int b = blockIdx.z / out_channels;
    int oc = blockIdx.z % out_channels;

    // Check if we're computing a valid output position
    if (row_out >= height_out || col_out >= width_out) return;

    // Calculate corresponding input position (top-left of kernel)
    int row_in = row_out;
    int col_in = col_out;

    float sum = 0.0f;

    // Loop over input channels
    for (int ic = 0; ic < in_channels; ic++) {
        // Calculate base pointers for this input channel
        const float* input_channel = &input[((b * in_channels + ic) * height_in + row_in) * width_in + col_in];
        const float* weight_channel = &weight[(oc * in_channels + ic) * KERNEL_SIZE * KERNEL_SIZE];

