#define THREADS_PER_BLOCK (BLOCK_SIZE_X * BLOCK_SIZE_Y)
#define K_SIZE 32

__global__ void tall_skinny_matmul_kernel(
    const float* A, const float* B, float* C,
    int M, int K, int N) {

    // Use 1D grid configuration for better memory access patterns
    int global_thread_id = blockIdx.x * THREADS_PER_BLOCK + threadIdx.x;

    // Each thread computes multiple output elements
    int elements_per_thread = (M * N + gridDim.x * THREADS_PER_BLOCK - 1) / (gridDim.x * THREADS_PER_BLOCK);

    for (int i = 0; i < elements_per_thread; ++i) {
        int idx = global_thread_id * elements_per_thread + i;
        if (idx >= M * N) break;

        int row = idx / N;
        int col = idx % N;

        float sum = 0.0f;

        // Prefetch A row (only once per row per thread)
        float a_vals[K_SIZE];
        if (i == 0) {
            for (int k = 0; k < K; ++k) {
                a_vals[k] = A[row * K + k];
            }
        }

        // Compute dot product - unroll loop for K=32
        for (int k = 0; k < K; ++k) {
            sum += (i == 0 ? a_vals[k] : A[row * K + k]) * B[k * N + col];
        }

        C[idx] = sum;
    }
}

